class NullAudio : public Audio {
public:
  virtual void playSound(int) {}
  virtual void stopSound(int) {}
  virtual void stopAllSounds() {}
};

class LoggedAudio : public Audio {
public:
  LoggedAudio(Audio& wrapped) : wrapped_(wrapped) {}
  virtual void playSound(int id) { log("play", id); wrapped_.playSound(id); }
  virtual void stopSound(int id) { log("stop", id); wrapped_.stopSound(id); }
  virtual void stopAllSounds() { log("stop all", -1); wrapped_.stopAllSounds(); }
private:
  void log(const char* what, int id);
  Audio& wrapped_;
};

void startup(const Args& args) {
  Locator::initialize();  // defaults to NullAudio
  if (!args.has("-nosound") && hasSoundDevice())
    Locator::provide(new ConsoleAudio());
  if (args.has("-logaudio"))
    Locator::provide(new LoggedAudio(Locator::getAudio()));
}

